MATCH (p:Painting)
WHERE EXISTS { MATCH (p)-[:hasGenre]->(g:Genre) WHERE toLower(g.name) = 'portrait' }
   OR EXISTS { MATCH (p)-[:associatedWith]->(a:ArtMovement) WHERE toLower(a.name) = 'academic art' }
RETURN count(p) AS count

MATCH (s:Sculpture)
WHERE EXISTS {
  MATCH (s)-[:createdBy]->(:Person {name: 'Auguste Rodin'})
} OR EXISTS {
  MATCH (s)-[:associatedWith]->(:ArtMovement {name: 'Modern sculpture'})
}
RETURN count(DISTINCT s) AS sculptureCount
